/tmp/probe-msg/mkcfg.sh /tmp/probe-msg/B - && cp B/in/foo.h /tmp/probe-msg/B/in/ 2>/dev/null; ls /tmp/probe-msg/B/in/

cd /tmp/probe-msg && mkdir -p W/in && cat > W/in/warn.h <<'EOF'
/** \file warn.h */

/** \brief A class. */
class Bar {
  public:
    /** \brief undocumented params here.
     *  \param a only a documented
     */
    void twoParams(int a, int b);

    /** \brief bad command usage.
     *  \nosuchcommand
     */
    void badCmd();

    /** \brief return doc but void
     *  \return something
     */
    void retVoid();

    /** \brief unknown param name
     *  \param zzz not a real param
     */
    void wrongParam(int q);

    int notDocumented;
};

/// undocumented struct member
struct Baz { int x; };

/** \brief doc for a nonexistent thing
 *  \ref NoSuchRef
 */
void refBad();
EOF
/tmp/probe-msg/mkcfg.sh /tmp/probe-msg/W - && printf 'WARN_NO_PARAMDOC = YES\n' >> W/Doxyfile && /tmp/probe-msg/run.sh /tmp/probe-msg/W 2>&1 | sed -n '/STDERR/,$p'

cd /tmp/probe-msg && mkdir -p W2/in && cat > W2/in/w2.h <<'EOF'
