#include "nosuchheader.h"

/** \brief No param docs at all. */
void noParamDocs(int a, int b);

/** \brief Partial docs.
 *  \param a doc for a
 */
void partialDocs(int a, int b);

/** \brief image missing
 *  \image html nosuchimage.png
 */
void img();

/** \brief dup label
 *  \anchor dupAnchor
 */
void d1();
/** \brief dup label 2
 *  \anchor dupAnchor
 */
void d2();
EOF
/tmp/probe-msg/mkcfg.sh /tmp/probe-msg/W2 - >/dev/null
printf 'WARN_NO_PARAMDOC = YES\nWARN_IF_INCOMPLETE_DOC = YES\n' >> W2/Doxyfile
echo "=== BASELINE ==="; rm -rf W2/out; /workspace/executable W2/Doxyfile >/dev/null 2>&1; /workspace/executable W2/Doxyfile >/dev/null 2>W2/e.txt; echo "EXIT=$?"; cat W2/e.txt
for opt in WARNINGS WARN_NO_PARAMDOC WARN_IF_INCOMPLETE_DOC WARN_IF_DOC_ERROR WARN_IF_UNDOCUMENTED; do
  cp W2/Doxyfile W2/Doxyfile.bak; printf '%s = NO\n' "$opt" >> W2/Doxyfile
  echo "=== $opt = NO ==="; rm -rf W2/out; /workspace/executable W2/Doxyfile >/dev/null 2>W2/e2.txt; echo "EXIT=$?"; diff W2/e.txt W2/e2.txt | sed 's/^/  /'
  mv W2/Doxyfile.bak W2/Doxyfile
done

cd /tmp/probe-msg && d=WLF; rm -rf $d; mkdir -p $d/in; cat > $d/in/dup.h <<'EOF'
