EOF
/tmp/probe-msg/mkcfg.sh /tmp/probe-msg/$d - >/dev/null
echo "### default WARN_LINE_FORMAT ###"
/workspace/executable $d/Doxyfile >/dev/null 2>$d/e1.txt; cat $d/e1.txt
